class TreeNode { constructor(val, left = null, right = null) { this.val = val; this.left = left; this.right = right; } }

// Iterative inorder: O(n) time, O(h) space
function inorder(root) {
  const out = [], stack = [];
  let cur = root;
  while (cur || stack.length) {
    while (cur) { stack.push(cur); cur = cur.left; }
    cur = stack.pop();
    out.push(cur.val);
    cur = cur.right;
  }
  return out;
}

// Level order with level boundaries
function levelOrder(root) {
  if (!root) return [];
  const res = [], q = [root];
  while (q.length) {
    const level = [], size = q.length;
    for (let i = 0; i < size; i++) {
      const n = q.shift();            // use an index pointer or deque for O(1) in large inputs
      level.push(n.val);
      if (n.left) q.push(n.left);
      if (n.right) q.push(n.right);
    }
    res.push(level);
  }
  return res;
}

// Validate BST with bounds
const isValidBST = (n, lo = -Infinity, hi = Infinity) =>
  !n || (n.val > lo && n.val < hi && isValidBST(n.left, lo, n.val) && isValidBST(n.right, n.val, hi));

// LCA in a general binary tree (bottom-up)
function lowestCommonAncestor(node, p, q) {
  if (!node || node === p || node === q) return node;
  const l = lowestCommonAncestor(node.left, p, q);
  const r = lowestCommonAncestor(node.right, p, q);
  return l && r ? node : l || r;
}

// Diameter: return height up, update global with two-sided path
function diameter(root) {
  let best = 0;
  (function h(n) {
    if (!n) return 0;
    const l = h(n.left), r = h(n.right);
    best = Math.max(best, l + r);
    return 1 + Math.max(l, r);
  })(root);
  return best;
}

from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None): self.val, self.left, self.right = val, left, right

def inorder(root):
    out, stack, cur = [], [], root
    while cur or stack:
        while cur:
            stack.append(cur); cur = cur.left
        cur = stack.pop()
        out.append(cur.val)
        cur = cur.right
    return out

def level_order(root):
    if not root: return []
    res, q = [], deque([root])
    while q:
        res.append([])
        for _ in range(len(q)):
            n = q.popleft()
            res[-1].append(n.val)
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
    return res

def is_valid_bst(n, lo=float("-inf"), hi=float("inf")):
    return n is None or (lo < n.val < hi and is_valid_bst(n.left, lo, n.val) and is_valid_bst(n.right, n.val, hi))

def lca_bst(root, p, q):                   # iterative, O(h)
    while root:
        if p.val < root.val and q.val < root.val: root = root.left
        elif p.val > root.val and q.val > root.val: root = root.right
        else: return root

def lca(node, p, q):
    if node in (None, p, q): return node
    l, r = lca(node.left, p, q), lca(node.right, p, q)
    return node if l and r else (l or r)

List<Integer> inorder(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    Deque<TreeNode> st = new ArrayDeque<>();
    TreeNode cur = root;
    while (cur != null || !st.isEmpty()) {
        while (cur != null) { st.push(cur); cur = cur.left; }
        cur = st.pop();
        out.add(cur.val);
        cur = cur.right;
    }
    return out;
}

boolean isValidBST(TreeNode n, long lo, long hi) {
    if (n == null) return true;
    if (n.val <= lo || n.val >= hi) return false;
    return isValidBST(n.left, lo, n.val) && isValidBST(n.right, n.val, hi);
}

TreeNode lowestCommonAncestor(TreeNode node, TreeNode p, TreeNode q) {
    if (node == null || node == p || node == q) return node;
    TreeNode l = lowestCommonAncestor(node.left, p, q), r = lowestCommonAncestor(node.right, p, q);
    return (l != null && r != null) ? node : (l != null ? l : r);
}

vector<int> inorder(TreeNode* root) {
    vector<int> out; stack<TreeNode*> st; TreeNode* cur = root;
    while (cur || !st.empty()) {
        while (cur) { st.push(cur); cur = cur->left; }
        cur = st.top(); st.pop();
        out.push_back(cur->val);
        cur = cur->right;
    }
    return out;
}

bool isValidBST(TreeNode* n, long long lo = LLONG_MIN, long long hi = LLONG_MAX) {
    if (!n) return true;
    if (n->val <= lo || n->val >= hi) return false;
    return isValidBST(n->left, lo, n->val) && isValidBST(n->right, n->val, hi);
}

TreeNode* lowestCommonAncestor(TreeNode* node, TreeNode* p, TreeNode* q) {
    if (!node || node == p || node == q) return node;
    TreeNode *l = lowestCommonAncestor(node->left, p, q), *r = lowestCommonAncestor(node->right, p, q);
    return (l && r) ? node : (l ? l : r);
}

// Immutable range sums
class NumArray {
  constructor(nums) {
    this.prefix = [0];
    for (const x of nums) this.prefix.push(this.prefix[this.prefix.length - 1] + x);
  }
  sumRange(l, r) { return this.prefix[r + 1] - this.prefix[l]; }
}

// Subarray Sum Equals K (negatives allowed): O(n)
function subarraySum(nums, k) {
  const seen = new Map([[0, 1]]);
  let cur = 0, ans = 0;
  for (const x of nums) {
    cur += x;
    ans += seen.get(cur - k) ?? 0;
    seen.set(cur, (seen.get(cur) ?? 0) + 1);
  }
  return ans;
}

// Car pooling with a difference array
function carPooling(trips, capacity) {
  const diff = new Array(1002).fill(0);
  for (const [n, from, to] of trips) { diff[from] += n; diff[to] -= n; } // passengers leave at 'to'
  let cur = 0;
  for (const d of diff) { cur += d; if (cur > capacity) return false; }
  return true;
}

from collections import defaultdict
from itertools import accumulate

class NumArray:
    def __init__(self, nums): self.prefix = [0, *accumulate(nums)]
    def sum_range(self, l, r): return self.prefix[r + 1] - self.prefix[l]

def subarray_sum(nums, k):
    seen, cur, ans = defaultdict(int, {0: 1}), 0, 0
    for x in nums:
        cur += x
        ans += seen[cur - k]
        seen[cur] += 1
    return ans

def subarrays_div_by_k(nums, k):
    seen, cur, ans = defaultdict(int, {0: 1}), 0, 0
    for x in nums:
        cur = (cur + x) % k              # Python's % is already non-negative for positive k
        ans += seen[cur]
        seen[cur] += 1
    return ans

def car_pooling(trips, capacity):
    diff = [0] * 1002
    for n, a, b in trips: diff[a] += n; diff[b] -= n
    return all(c <= capacity for c in accumulate(diff))

class NumArray {
    private final long[] prefix;
    NumArray(int[] nums) {
        prefix = new long[nums.length + 1];
        for (int i = 0; i < nums.length; i++) prefix[i + 1] = prefix[i] + nums[i];
    }
    long sumRange(int l, int r) { return prefix[r + 1] - prefix[l]; }
}

int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> seen = new HashMap<>();
    seen.put(0, 1);
    int cur = 0, ans = 0;
    for (int x : nums) {
        cur += x;
        ans += seen.getOrDefault(cur - k, 0);
        seen.merge(cur, 1, Integer::sum);
    }
    return ans;
}

int subarraysDivByK(int[] nums, int k) {
    int[] count = new int[k]; count[0] = 1;
    int cur = 0, ans = 0;
    for (int x : nums) {
        cur = ((cur + x) % k + k) % k;       // fix negative remainders
        ans += count[cur]++;
    }
    return ans;
}

class NumMatrix {
    vector<vector<int>> P;
public:
    NumMatrix(vector<vector<int>>& a) {
        int m = a.size(), n = a[0].size();
        P.assign(m + 1, vector<int>(n + 1, 0));
        for (int i = 1; i <= m; i++)
            for (int j = 1; j <= n; j++)
                P[i][j] = a[i-1][j-1] + P[i-1][j] + P[i][j-1] - P[i-1][j-1];
    }
    int sumRegion(int r1, int c1, int r2, int c2) {
        return P[r2+1][c2+1] - P[r1][c2+1] - P[r2+1][c1] + P[r1][c1];
    }
};

int subarraySum(vector<int>& nums, int k) {
    unordered_map<int,int> seen; seen[0] = 1;
    int cur = 0, ans = 0;
    for (int x : nums) { cur += x; ans += seen[cur - k]; seen[cur]++; }
    return ans;
}

// Fenwick tree: point update, prefix/range sum
class Fenwick {
  constructor(n) { this.n = n; this.t = new Array(n + 1).fill(0); }
  update(i, delta) { for (i++; i <= this.n; i += i & -i) this.t[i] += delta; }   // 0-based API
  prefix(i) { let s = 0; for (i++; i > 0; i -= i & -i) s += this.t[i]; return s; } // sum of [0..i]
  range(l, r) { return this.prefix(r) - (l ? this.prefix(l - 1) : 0); }
}

// Iterative segment tree (sum), point update + range query, half-open [l, r)
class SegTree {
  constructor(a) {
    this.n = a.length; this.t = new Array(2 * this.n).fill(0);
    for (let i = 0; i < this.n; i++) this.t[this.n + i] = a[i];
    for (let i = this.n - 1; i > 0; i--) this.t[i] = this.t[2 * i] + this.t[2 * i + 1];
  }
  update(i, v) { for (this.t[i += this.n] = v; i > 1; i >>= 1) this.t[i >> 1] = this.t[i] + this.t[i ^ 1]; }
  query(l, r) { let s = 0; for (l += this.n, r += this.n; l < r; l >>= 1, r >>= 1) { if (l & 1) s += this.t[l++]; if (r & 1) s += this.t[--r]; } return s; }
}

class Fenwick:
    def __init__(self, n): self.n, self.t = n, [0] * (n + 1)
    def update(self, i, delta):            # i is 0-based
        i += 1
        while i <= self.n:
            self.t[i] += delta
            i += i & -i
    def prefix(self, i):                   # sum of [0..i]
        i += 1; s = 0
        while i > 0:
            s += self.t[i]
            i -= i & -i
        return s
    def range(self, l, r): return self.prefix(r) - (self.prefix(l - 1) if l else 0)

# Count inversions with a Fenwick tree over compressed ranks
def count_inversions(a):
    ranks = {v: i for i, v in enumerate(sorted(set(a)))}
    bit, inv = Fenwick(len(ranks)), 0
    for x in reversed(a):                  # how many smaller values already appeared to the right?
        r = ranks[x]
        inv += bit.prefix(r - 1) if r else 0
        bit.update(r, 1)
    return inv

class SegTreeMin:                           # iterative min tree, half-open [l, r)
    def __init__(self, a):
        self.n = len(a); self.t = [float("inf")] * self.n + list(a)
        for i in range(self.n - 1, 0, -1): self.t[i] = min(self.t[2*i], self.t[2*i+1])
    def update(self, i, v):
        i += self.n; self.t[i] = v
        while i > 1: i >>= 1; self.t[i] = min(self.t[2*i], self.t[2*i+1])
    def query(self, l, r):
        res = float("inf"); l += self.n; r += self.n
        while l < r:
            if l & 1: res = min(res, self.t[l]); l += 1
            if r & 1: r -= 1; res = min(res, self.t[r])
            l >>= 1; r >>= 1
        return res

class Fenwick {
    private final long[] t;
    Fenwick(int n) { t = new long[n + 1]; }
    void update(int i, long delta) { for (i++; i < t.length; i += i & -i) t[i] += delta; }
    long prefix(int i) { long s = 0; for (i++; i > 0; i -= i & -i) s += t[i]; return s; }
    long range(int l, int r) { return prefix(r) - (l > 0 ? prefix(l - 1) : 0); }
}

class SegTree {   // sum, half-open [l, r)
    final int n; final long[] t;
    SegTree(int[] a) {
        n = a.length; t = new long[2 * n];
        for (int i = 0; i < n; i++) t[n + i] = a[i];
        for (int i = n - 1; i > 0; i--) t[i] = t[2 * i] + t[2 * i + 1];
    }
    void update(int i, long v) { for (t[i += n] = v; i > 1; i >>= 1) t[i >> 1] = t[i] + t[i ^ 1]; }
    long query(int l, int r) {
        long s = 0;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) s += t[l++];
            if ((r & 1) == 1) s += t[--r];
        }
        return s;
    }
}

struct Fenwick {
    vector<long long> t;
    Fenwick(int n) : t(n + 1, 0) {}
    void update(int i, long long d) { for (i++; i < (int)t.size(); i += i & -i) t[i] += d; }
    long long prefix(int i) { long long s = 0; for (i++; i > 0; i -= i & -i) s += t[i]; return s; }
    long long range(int l, int r) { return prefix(r) - (l ? prefix(l - 1) : 0); }
};

// Lazy segment tree: range add, range sum (recursive)
struct Lazy {
    int n; vector<long long> sum, add;
    Lazy(int n) : n(n), sum(4 * n, 0), add(4 * n, 0) {}
    void apply(int o, int l, int r, long long v) { sum[o] += v * (r - l + 1); add[o] += v; }
    void push(int o, int l, int r) {
        if (!add[o]) return;
        int m = (l + r) / 2;
        apply(2*o, l, m, add[o]); apply(2*o+1, m+1, r, add[o]); add[o] = 0;
    }
    void update(int o, int l, int r, int ql, int qr, long long v) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) { apply(o, l, r, v); return; }
        push(o, l, r);
        int m = (l + r) / 2;
        update(2*o, l, m, ql, qr, v); update(2*o+1, m+1, r, ql, qr, v);
        sum[o] = sum[2*o] + sum[2*o+1];
    }
    long long query(int o, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return sum[o];
        push(o, l, r);
        int m = (l + r) / 2;
        return query(2*o, l, m, ql, qr) + query(2*o+1, m+1, r, ql, qr);
    }
};
